                if (runBatch.NotesOption.Value != null)
                    writer.WriteString("notes", runBatch.Notes);
                else
                    writer.WriteNull("notes");

            if (runBatch.SpecRunIdsOption.IsSet)
            {
                writer.WritePropertyName("specRunIds");
                JsonSerializer.Serialize(writer, runBatch.SpecRunIds, jsonSerializerOptions);
            }
            if (runBatch.UiMacroRunIdsOption.IsSet)
            {
                writer.WritePropertyName("uiMacroRunIds");
                JsonSerializer.Serialize(writer, runBatch.UiMacroRunIds, jsonSerializerOptions);
            }
            if (runBatch.FlowRunIdsOption.IsSet)
            {
                writer.WritePropertyName("flowRunIds");
                JsonSerializer.Serialize(writer, runBatch.FlowRunIds, jsonSerializerOptions);
            }
            if (runBatch.FinishedAtOption.IsSet)
                if (runBatch.FinishedAtOption.Value != null)
                    writer.WriteString("finishedAt", runBatch.FinishedAtOption.Value!.Value.ToString(FinishedAtFormat));
                else
                    writer.WriteNull("finishedAt");
        }
    }
}
